/* From Uiverse.io by solanodz - Tags: switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgb(255, 255, 255);
  transition: .5s;
  border-radius: 0px;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 0px;
  left: 0.3em;
  bottom: 0.3em;
  background-color: rgb(0, 0, 0);
  transition: .5s;
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background-color: #06c235;
}

.__UIV_SCOPE__ .switch input:focus + .slider {
  box-shadow: 0 0 1px #000000;
}

.__UIV_SCOPE__ .switch input:checked + .slider:before {
  transform: translateX(1.5em);
}
